-- [M06002_TEMPLATE_ENSURE_TABLE]
DECLARE
    V_COUNT NUMBER;
BEGIN
    SELECT COUNT(*)
      INTO V_COUNT
      FROM USER_TABLES
     WHERE TABLE_NAME = 'INIT$_TB_REPORT_TEMPLATE';

    IF V_COUNT = 0 THEN
        BEGIN
            EXECUTE IMMEDIATE q'[
CREATE TABLE "INIT$_TB_REPORT_TEMPLATE" (
    "TEMPLATE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY NOT NULL ENABLE
  , "USER_ID" NUMBER NOT NULL ENABLE
  , "TEMPLATE_NAME" VARCHAR2(200 CHAR) NOT NULL ENABLE
  , "TEMPLATE_DESC" VARCHAR2(1000 CHAR)
  , "PAPER_SIZE" VARCHAR2(2 BYTE) DEFAULT 'A4' NOT NULL ENABLE
  , "ORIENTATION" VARCHAR2(10 BYTE) DEFAULT 'PORTRAIT' NOT NULL ENABLE
  , "LAYOUT_JSON" CLOB NOT NULL ENABLE
  , "REPORT_COUNT" NUMBER DEFAULT 0 NOT NULL ENABLE
  , "SCHEMA_VERSION" VARCHAR2(30 BYTE) DEFAULT '1.0' NOT NULL ENABLE
  , "TEMPLATE_VERSION" NUMBER DEFAULT 1 NOT NULL ENABLE
  , "USE_YN" CHAR(1 BYTE) DEFAULT 'Y' NOT NULL ENABLE
  , "CREATED_AT" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE
  , "UPDATED_AT" TIMESTAMP (6)
  , CONSTRAINT "INIT$_PK_CUSTOM_REPORT_TMPL" PRIMARY KEY ("TEMPLATE_ID")
  , CONSTRAINT "INIT$_CK_CUSTOM_REPORT_PAPER" CHECK ("PAPER_SIZE" IN ('A4', 'A3')) ENABLE
  , CONSTRAINT "INIT$_CK_CUSTOM_REPORT_ORIENT" CHECK ("ORIENTATION" IN ('PORTRAIT', 'LANDSCAPE')) ENABLE
  , CONSTRAINT "INIT$_CK_CUSTOM_REPORT_COUNT" CHECK ("REPORT_COUNT" BETWEEN 0 AND 20) ENABLE
  , CONSTRAINT "INIT$_CK_CUSTOM_REPORT_USE" CHECK ("USE_YN" IN ('Y', 'N')) ENABLE
)
]';
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -955 THEN
                    RAISE;
                END IF;
        END;
    END IF;

    SELECT COUNT(*)
      INTO V_COUNT
      FROM USER_INDEXES
     WHERE INDEX_NAME = 'INIT$_IX_CUSTOM_REPORT_USER';

    IF V_COUNT = 0 THEN
        BEGIN
            EXECUTE IMMEDIATE 'CREATE INDEX "INIT$_IX_CUSTOM_REPORT_USER" ON "INIT$_TB_REPORT_TEMPLATE" ("USER_ID", "USE_YN", "UPDATED_AT")';
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -955 THEN
                    RAISE;
                END IF;
        END;
    END IF;

    SELECT COUNT(*)
      INTO V_COUNT
      FROM USER_TABLES
     WHERE TABLE_NAME = 'INIT$_TB_REPORT_TMPL_USE';

    IF V_COUNT = 0 THEN
        BEGIN
            EXECUTE IMMEDIATE q'[
CREATE TABLE "INIT$_TB_REPORT_TMPL_USE" (
    "TEMPLATE_USE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY NOT NULL ENABLE
  , "TEMPLATE_ID" NUMBER NOT NULL ENABLE
  , "USER_ID" NUMBER NOT NULL ENABLE
  , "PROJECT_ID" NUMBER NOT NULL ENABLE
  , "LAST_SCENARIO_ID" NUMBER
  , "USE_COUNT" NUMBER DEFAULT 1 NOT NULL ENABLE
  , "CREATED_AT" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE
  , "LAST_USED_AT" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE
  , CONSTRAINT "INIT$_PK_REPORT_TMPL_USE" PRIMARY KEY ("TEMPLATE_USE_ID")
  , CONSTRAINT "INIT$_FK_RPT_USE_TEMPLATE" FOREIGN KEY ("TEMPLATE_ID")
        REFERENCES "INIT$_TB_REPORT_TEMPLATE" ("TEMPLATE_ID") ON DELETE CASCADE ENABLE
  , CONSTRAINT "INIT$_FK_RPT_USE_PROJECT" FOREIGN KEY ("PROJECT_ID")
        REFERENCES "INIT$_TB_PROJECT" ("PROJECT_ID") ON DELETE CASCADE ENABLE
  , CONSTRAINT "INIT$_FK_RPT_USE_SCENARIO" FOREIGN KEY ("LAST_SCENARIO_ID")
        REFERENCES "INIT$_TB_SCENARIO" ("SCENARIO_ID") ON DELETE SET NULL ENABLE
  , CONSTRAINT "INIT$_UK_RPT_USE_CONTEXT" UNIQUE ("USER_ID", "PROJECT_ID", "TEMPLATE_ID")
  , CONSTRAINT "INIT$_CK_RPT_USE_COUNT" CHECK ("USE_COUNT" >= 1) ENABLE
)
]';
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -955 THEN
                    RAISE;
                END IF;
        END;
    END IF;

    SELECT COUNT(*)
      INTO V_COUNT
      FROM USER_INDEXES
     WHERE INDEX_NAME = 'INIT$_IX_RPT_USE_PROJECT';

    IF V_COUNT = 0 THEN
        BEGIN
            EXECUTE IMMEDIATE 'CREATE INDEX "INIT$_IX_RPT_USE_PROJECT" ON "INIT$_TB_REPORT_TMPL_USE" ("USER_ID", "PROJECT_ID", "LAST_USED_AT")';
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLCODE != -955 THEN
                    RAISE;
                END IF;
        END;
    END IF;
END;

-- [M06002_TEMPLATE_LIST]
SELECT TEMPLATE_ID
     , TEMPLATE_NAME
     , TEMPLATE_DESC
     , PAPER_SIZE
     , ORIENTATION
     , REPORT_COUNT
     , SCHEMA_VERSION
     , TEMPLATE_VERSION
     , CREATED_AT
     , UPDATED_AT
  FROM INIT$_TB_REPORT_TEMPLATE
 WHERE 1=1
   AND USER_ID = :userId
   AND USE_YN = 'Y'
 ORDER BY NVL(UPDATED_AT, CREATED_AT) DESC
        , TEMPLATE_ID DESC
;

-- [M06002_TEMPLATE_DETAIL]
SELECT TEMPLATE_ID
     , TEMPLATE_NAME
     , TEMPLATE_DESC
     , PAPER_SIZE
     , ORIENTATION
     , LAYOUT_JSON
     , REPORT_COUNT
     , SCHEMA_VERSION
     , TEMPLATE_VERSION
     , CREATED_AT
     , UPDATED_AT
  FROM INIT$_TB_REPORT_TEMPLATE
 WHERE 1=1
   AND TEMPLATE_ID = :templateId
   AND USER_ID = :userId
   AND USE_YN = 'Y'
;

-- [M06002_TEMPLATE_INSERT]
INSERT INTO INIT$_TB_REPORT_TEMPLATE (
    USER_ID
  , TEMPLATE_NAME
  , TEMPLATE_DESC
  , PAPER_SIZE
  , ORIENTATION
  , LAYOUT_JSON
  , REPORT_COUNT
  , SCHEMA_VERSION
  , TEMPLATE_VERSION
  , USE_YN
  , CREATED_AT
) VALUES (
    :userId
  , :templateName
  , :templateDesc
  , :paperSize
  , :orientation
  , :layoutJson
  , :reportCount
  , :schemaVersion
  , 1
  , 'Y'
  , SYSTIMESTAMP
)
RETURNING TEMPLATE_ID INTO :templateIdOut
;

-- [M06002_TEMPLATE_UPDATE]
UPDATE INIT$_TB_REPORT_TEMPLATE
   SET TEMPLATE_NAME = :templateName
     , TEMPLATE_DESC = :templateDesc
     , PAPER_SIZE = :paperSize
     , ORIENTATION = :orientation
     , LAYOUT_JSON = :layoutJson
     , REPORT_COUNT = :reportCount
     , SCHEMA_VERSION = :schemaVersion
     , TEMPLATE_VERSION = TEMPLATE_VERSION + 1
     , UPDATED_AT = SYSTIMESTAMP
 WHERE 1=1
   AND TEMPLATE_ID = :templateId
   AND USER_ID = :userId
   AND USE_YN = 'Y'
   AND (:expectedVersion IS NULL OR TEMPLATE_VERSION = :expectedVersion)
;

-- [M06002_TEMPLATE_DELETE]
UPDATE INIT$_TB_REPORT_TEMPLATE
   SET USE_YN = 'N'
     , UPDATED_AT = SYSTIMESTAMP
 WHERE 1=1
   AND TEMPLATE_ID = :templateId
   AND USER_ID = :userId
   AND USE_YN = 'Y'
;

-- [M06002_TEMPLATE_USAGE_MERGE]
MERGE INTO INIT$_TB_REPORT_TMPL_USE U
USING (
      SELECT TEMPLATE_ID
        FROM INIT$_TB_REPORT_TEMPLATE
       WHERE 1=1
         AND TEMPLATE_ID = :templateId
         AND USER_ID = :userId
         AND USE_YN = 'Y'
      ) T
   ON (
          U.USER_ID = :userId
      AND U.PROJECT_ID = :projectId
      AND U.TEMPLATE_ID = T.TEMPLATE_ID
      )
 WHEN MATCHED THEN
      UPDATE
         SET U.LAST_SCENARIO_ID = :scenarioId
           , U.USE_COUNT = U.USE_COUNT + 1
           , U.LAST_USED_AT = SYSTIMESTAMP
 WHEN NOT MATCHED THEN
      INSERT (
          TEMPLATE_ID
        , USER_ID
        , PROJECT_ID
        , LAST_SCENARIO_ID
        , USE_COUNT
        , CREATED_AT
        , LAST_USED_AT
      ) VALUES (
          T.TEMPLATE_ID
        , :userId
        , :projectId
        , :scenarioId
        , 1
        , SYSTIMESTAMP
        , SYSTIMESTAMP
      )
;

-- [M06002_PROJECT_REPORT_USAGE_LIST]
SELECT U.PROJECT_ID
     , U.TEMPLATE_ID
     , T.TEMPLATE_NAME
     , T.PAPER_SIZE
     , T.ORIENTATION
     , T.REPORT_COUNT
     , U.LAST_SCENARIO_ID
     , U.USE_COUNT
     , U.CREATED_AT
     , U.LAST_USED_AT
  FROM INIT$_TB_REPORT_TMPL_USE U
  JOIN INIT$_TB_REPORT_TEMPLATE T
    ON T.TEMPLATE_ID = U.TEMPLATE_ID
   AND T.USER_ID = U.USER_ID
   AND T.USE_YN = 'Y'
 WHERE 1=1
   AND U.USER_ID = :userId
   AND INSTR(',' || :projectIds || ',', ',' || TO_CHAR(U.PROJECT_ID) || ',') > 0
 ORDER BY U.PROJECT_ID
        , U.LAST_USED_AT DESC
        , U.TEMPLATE_USE_ID DESC
;
